(7267867, 1130803, 13077, '<td valign="top">Very cool. Simple and busy at the same time, but the random colors and the wave patterns look great.</td>', 'Very cool. Simple and busy at the same time, but the random colors and the wave patterns look great.', '2014-09-30 22:04:00.000000', NULL, 1),
(7267868, 1130592, 13077, '<td valign="top">Yikes!</td>', 'Yikes!', '2014-09-30 22:04:12.000000', NULL, 1),
(7267870, 1130883, 13077, '<td valign="top">Great job capturing the sand with lots of detail and still getting the detail in the man''s legs and the sky. I like the composition very much as well.</td>', 'Great job capturing the sand with lots of detail and still getting the detail in the man''s legs and the sky. I like the composition very much as well.', '2014-09-30 22:04:55.000000', NULL, 1),
(7267871, 1130550, 13077, '<td valign="top">I like the surface used as a backdrop here, it looks very intriguing when slightly out of focus like that. Great detail in the glass edges too.</td>', 'I like the surface used as a backdrop here, it looks very intriguing when slightly out of focus like that. Great detail in the glass edges too.', '2014-09-30 22:06:02.000000', NULL, 1),
(7267878, 1130758, 13077, '<td valign="top">Nice slice of life here, I like it.</td>', 'Nice slice of life here, I like it.', '2014-09-30 22:12:19.000000', NULL, 1),
