(7267882, 1130824, 13077, '<td valign="top">Very cool concept and well executed. I like the overall funky look, and that little handicap sign.</td>', 'Very cool concept and well executed. I like the overall funky look, and that little handicap sign.', '2014-09-30 22:19:23.000000', NULL, 1),
(7267884, 1130792, 13077, '<td valign="top">Nice scene, but some processing to bring up the detail in the shadows might have helped.</td>', 'Nice scene, but some processing to bring up the detail in the shadows might have helped.', '2014-09-30 22:20:04.000000', NULL, 1),
(7267886, 1130833, 13077, '<td valign="top">Excellent tones and color, just enough detail in the surface of the petals and sharp highlighted edges. I like it a lot.</td>', 'Excellent tones and color, just enough detail in the surface of the petals and sharp highlighted edges. I like it a lot.', '2014-09-30 22:29:19.000000', NULL, 1),
(7267889, 1130874, 13077, '<td valign="top">I like it - nice job bringing a statue to ''life'', with a visually pleasing and interesting photo at that.</td>', 'I like it - nice job bringing a statue to ''life'', with a visually pleasing and interesting photo at that.', '2014-09-30 22:35:45.000000', NULL, 1),
(7267891, 1130810, 13077, '<td valign="top">Nicely lit and processed, and I like the concept.</td>', 'Nicely lit and processed, and I like the concept.', '2014-09-30 22:37:01.000000', NULL, 1),
(7267894, 1130593, 13077, '<td valign="top">Nicely composed. Lots of noise but maybe that was what you were going for.</td>', 'Nicely composed. Lots of noise but maybe that was what you were going for.', '2014-09-30 22:40:09.000000', NULL, 1),
(7267897, 1130625, 13077, '<td valign="top">Such an interesting door. Well portrayed, and full of edges.</td>', 'Such an interesting door. Well portrayed, and full of edges.', '2014-09-30 22:42:49.000000', NULL, 1),
(7267898, 1130880, 13077, '<td valign="top">Great concept, very well done.</td>', 'Great concept, very well done.', '2014-09-30 22:43:13.000000', NULL, 1),
