(7267900, 1130858, 13077, '<td valign="top">Until it got "edged" out by the 6. lol</td>', 'Until it got "edged" out by the 6. lol', '2014-09-30 22:47:13.000000', NULL, 1),
(7267902, 1130818, 13077, '<td valign="top">I like the bold shapes and colors here. However, the only thing tying it to the edge theme seems to be your title.</td>', 'I like the bold shapes and colors here. However, the only thing tying it to the edge theme seems to be your title.', '2014-09-30 22:47:54.000000', NULL, 1),
(7267903, 1130556, 13077, '<td valign="top">Full of edges, and edgy processing. Even has grass with lots of edges at the bottom... edge!</td>', 'Full of edges, and edgy processing. Even has grass with lots of edges at the bottom... edge!', '2014-09-30 22:49:00.000000', NULL, 1),
(7267904, 1130885, 13077, '<td valign="top">Interesting abstract, but I wonder how it would have worked with more of a square crop?</td>', 'Interesting abstract, but I wonder how it would have worked with more of a square crop?', '2014-09-30 22:49:52.000000', NULL, 1),
(7267905, 1130831, 13077, '<td valign="top">Jump for sure!</td>', 'Jump for sure!', '2014-09-30 22:50:07.000000', NULL, 1),
(7267906, 1130876, 13077, '<td valign="top">Looks like quite a character. Nicely done with the harsh lighting conditions.</td>', 'Looks like quite a character. Nicely done with the harsh lighting conditions.', '2014-09-30 22:54:54.000000', NULL, 1),
(7267907, 1130863, 13077, '<td valign="top">An early 70''s corvette?</td>', 'An early 70''s corvette?', '2014-09-30 23:04:30.000000', NULL, 1),
