(7267909, 1130521, 13077, '<td valign="top">The composition and light look pretty good, but the grain and lack of focus on the edges of the petals hurt it.</td>', 'The composition and light look pretty good, but the grain and lack of focus on the edges of the petals hurt it.', '2014-09-30 23:07:11.000000', NULL, 1),
(7267910, 1130878, 13077, '<td valign="top">Beautiful place, and it''s certainly full of edges. Nicely done.</td>', 'Beautiful place, and it''s certainly full of edges. Nicely done.', '2014-09-30 23:08:14.000000', NULL, 1),
(7267911, 1130870, 13077, '<td valign="top">Very cool. Visually everything about it just works. Hope it does well.</td>', 'Very cool. Visually everything about it just works. Hope it does well.', '2014-09-30 23:09:19.000000', NULL, 1),
(7267912, 1130487, 13077, '<td valign="top">I wish the edge of the blade was more visible and prominent here.</td>', 'I wish the edge of the blade was more visible and prominent here.', '2014-09-30 23:10:22.000000', NULL, 1),
(7267913, 1130349, 13077, '<td valign="top">It does have edges, and corners...</td>', 'It does have edges, and corners...', '2014-09-30 23:11:10.000000', NULL, 1),
